lines = sum(f['summary']['lines']['covered'] for f in source)
underlying_lines = sum(f['summary']['lines']['covered'] for f in underlying)
if lines == 0 or underlying_lines == 0:
    raise SystemExit('no POCO JSON or bundled pdjson source lines covered')
parser_lines = sum(f['summary']['lines']['covered'] for f in source
                   if f['filename'].endswith('/JSON/src/ParserImpl.cpp'))
pdjson_lines = sum(f['summary']['lines']['covered'] for f in underlying
                   if f['filename'].endswith('/pdjson.c'))
