    raise SystemExit('no POCO ParserImpl.cpp or pdjson.c source lines covered')
result = {'control_pass': True, 'output': observed, 'exact_nested_structure_match': True,
          'parser_source_files': len(source), 'parser_source_lines_covered': lines,
          'format_specific_source_lines_covered': parser_lines,
          'underlying_source_files': len(underlying),
          'underlying_source_lines_covered': underlying_lines,
          'underlying_format_specific_source_lines_covered': pdjson_lines,
          'coverage': '/coverage/coverage.json'}
Path('/coverage/summary.json').write_text(json.dumps(result, indent=2) + '\n')
